draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Book
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.rect(W/2 - 50, H/2 - 50, 100, 100);
  ctx.fill();
  ctx.stroke();

  // Pages turning
  ctx.beginPath();
  ctx.rect(W/2 - 40, H/2 - 40, 80, 80);
  ctx.fillStyle = 'white';
  ctx.fill();
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.stroke();
  ctx.beginPath();
  ctx.rect(W/2 - 40 + 20 * Math.sin(t), H/2 - 40, 40, 80);
  ctx.fillStyle = 'white';
  ctx.fill();
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // Stick figure reading
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 120, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 120, H/2 + 20);
  ctx.lineTo(W/2 - 120, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 120, H/2 + 30);
  ctx.lineTo(W/2 - 100, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 120, H/2 + 30);
  ctx.lineTo(W/2 - 140, H/2 + 50);
  ctx.stroke();

  // Lightbulb above head
  ctx.beginPath();
  ctx.arc(W/2 - 120, H/2 - 30 + 10 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.fillStyle = 'yellow';
  ctx.fill();
  ctx.stroke();

  ctx.restore();
}
